def load_notes() -> dict:
    if not NOTES_PATH.is_file():
        return {}
    try:
        data = json.loads(NOTES_PATH.read_text("utf-8"))
        return {
            str(name): str(value)
            for name, value in data.items()
            if isinstance(name, str) and isinstance(value, str) and value.strip()
        } if isinstance(data, dict) else {}
    except Exception:
        return {}


def save_notes() -> None:
    NOTES_PATH.parent.mkdir(parents=True, exist_ok=True)
    temporary = NOTES_PATH.with_suffix(".tmp")
    temporary.write_text(
        json.dumps(MANUAL_NOTES, ensure_ascii=False, indent=2), "utf-8"
    )
    temporary.replace(NOTES_PATH)


MANUAL_NOTES = load_notes()


def clean_description(value: object) -> str:
    """将源码中的说明整理成适合 Telegram 单行显示的文字。"""
    text = re.sub(r"<[^>]+>", "", str(value or ""))
    text = re.sub(r"\s+", " ", text).strip(" .。；;")
    for prefix in ("PagerMaid-Pyro:", "PagerMaid-Pyro：", "PagerMaid:", "PagerMaid："):
        if text.lower().startswith(prefix.lower()):
            text = text[len(prefix):].strip()
            break
    if not text:
        return "暂无功能说明"
    first = re.split(r"(?<=[。！？!?])\s+|\n", text, maxsplit=1)[0].strip()
    if len(first) > 80:
        first = first[:77].rstrip() + "…"
    return first


def literal_string(node: ast.AST) -> Optional[str]:
    try:
        value = ast.literal_eval(node)
    except (ValueError, TypeError, SyntaxError):
        return None
    return value if isinstance(value, str) else None


def listener_descriptions(tree: ast.Module) -> List[str]:
    descriptions: List[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        for decorator in node.decorator_list:
            if not isinstance(decorator, ast.Call):
                continue
            function = decorator.func
            is_listener = (
                isinstance(function, ast.Name) and function.id == "listener"
            ) or (
                isinstance(function, ast.Attribute) and function.attr == "listener"
            )
            if not is_listener:
                continue
            for keyword in decorator.keywords:
                if keyword.arg == "description":
                    value = literal_string(keyword.value)
                    if value:
                        description = clean_description(value)
                        if description not in descriptions:
                            descriptions.append(description)
    return descriptions


def describe_plugin(path: Path) -> str:
    """静态读取插件说明，不导入或执行插件代码。"""
    try:
        source = path.read_text("utf-8-sig")
        tree = ast.parse(source, filename=str(path))
    except (OSError, UnicodeError, SyntaxError):
        return "无法读取插件说明"

    descriptions = listener_descriptions(tree)
    if descriptions:
        return clean_description("；".join(descriptions))

    docstring = ast.get_docstring(tree, clean=True)
    if docstring:
        return clean_description(docstring)
    return "暂无功能说明"


def plugin_files(directory: Path) -> List[Path]:
    if not directory.is_dir():
        return []
    return sorted(
        (
            path
            for path in directory.glob("*.py")
            if path.is_file() and path.name != "__init__.py"
        ),
        key=lambda path: path.name.casefold(),
    )


def resolve_plugin(value: str) -> Optional[Path]:
    name = Path(value.strip()).name
    if not name or name != value.strip() or any(mark in value for mark in ("/", "\\")):
        return None
    wanted = name.casefold()
    if not wanted.endswith(".py"):
        wanted += ".py"
    return next(
        (path for path in plugin_files(PLUGINS_DIR) if path.name.casefold() == wanted),
        None,
    )


def effective_description(path: Path) -> str:
    if path.name in MANUAL_NOTES:
        return MANUAL_NOTES[path.name]
    if path.name in DESCRIPTION_OVERRIDES:
        return DESCRIPTION_OVERRIDES[path.name]
    return describe_plugin(path)


def format_entries(paths: Iterable[Path]) -> List[str]:
    return [
        f"<b>{index:02d}  {html.escape(path.name)}</b>\n"
        f"{html.escape(clean_description(effective_description(path)))}"
        for index, path in enumerate(paths, 1)
    ]




def count_caption(paths, entries):
    if not entries:
        return "没有找到插件脚本。"
    return "<blockquote>" + "\n\n".join(entries) + "</blockquote>"


def process_uptime_seconds():
    """PagerMaid process lifetime, using the same psutil method as zt.py."""
    try:
        import psutil
        return max(0.0, time.time() - psutil.Process().create_time())
    except Exception:
        return None


def format_process_uptime(seconds):
    if seconds is None:
        return "运行时间未获取"
    minutes = max(0, int(seconds)) // 60
    days, remainder = divmod(minutes, 1440)
    hours = remainder // 60
    if days:
        return f"已运行 {days}天{hours}小时"
    if hours:
        return f"已运行 {hours}小时"
    if minutes:
        return f"已运行 {minutes}分钟"
    return "已运行 不足1分钟"


def create_count_card(count, uptime_seconds=None):
    from PIL import Image, ImageDraw, ImageFilter, ImageFont

    data = {"regular": _CJ_FONT_REGULAR_B64, "bold": _CJ_FONT_BOLD_B64, "latin": _CJ_FONT_LATIN_B64}
    fonts = {(kind, size): ImageFont.truetype(io.BytesIO(base64.b64decode(value)), size)
             for kind, value in data.items() for size in (28, 32, 46, 154)}
    image = Image.new("RGBA", (1200, 600), "#05070d")
    ambient = Image.new("RGBA", image.size, (0, 0, 0, 0))
    glow = ImageDraw.Draw(ambient)
    glow.ellipse((820, -260, 1440, 360), fill=(36, 211, 238, 30))
    glow.ellipse((-260, 440, 340, 1000), fill=(139, 92, 246, 18))
    image = Image.alpha_composite(image, ambient.filter(ImageFilter.GaussianBlur(120)))
    draw = ImageDraw.Draw(image)

    def runs(value, size, bold):
        for part in re.findall(r"[\x00-\x7f]+|[^\x00-\x7f]+", value):
            kind = ("latin" if part.isascii() else "bold") if bold else "regular"
            yield part, fonts[kind, size]

    def measure(value, size, bold=True):
        return sum(draw.textlength(part, font=font) for part, font in runs(value, size, bold))

    def text(x, baseline, value, size, color="#f8fafc", bold=True):
        for part, font in runs(value, size, bold):
            draw.text((x, baseline), part, font=font, fill=color, anchor="ls")
            x += draw.textlength(part, font=font)

    text(64, 98, "Yanyu", 46)
    text(64 + measure("Yanyu", 46), 98, "Bot", 46, "#38d6ee")
    text(64 + measure("YanyuBot", 46) + 16, 98, "插件", 46)
    subtitle = format_process_uptime(process_uptime_seconds() if uptime_seconds is None else uptime_seconds)
    text(1136 - measure(subtitle, 28), 98, subtitle, 28, "#b6c3d5")
    draw.line((64, 137, 1136, 137), fill="#1b2636", width=2)
    value = str(max(0, int(count)))
    text((1200 - measure(value, 154)) / 2, 386, value, 154)
    label = "已安装插件"
    text((1200 - measure(label, 32, False)) / 2, 454, label, 32, "#a8b5c8", False)
    output = io.BytesIO()
    image.convert("RGB").save(output, "PNG", optimize=True)
    output.name = "pagermaid-plugin-count.png"
    output.seek(0)
    return output


def full_inventory_font():
    """Use a local CJK font; cache the licensed Noto font only if needed."""
    candidates = (
        Path("/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc"),
        Path("/usr/share/fonts/truetype/wqy/wqy-zenhei.ttc"),
        Path("C:/Windows/Fonts/msyh.ttc"),
    )
    for path in candidates:
        if path.is_file():
            return path
    path = NOTES_PATH.parent / "cj-fonts" / "NotoSansCJKsc-Regular.otf"
    expected = "2c76254f6fc379fddfce0a7e84fb5385bb135d3e399294f6eeb6680d0365b74b"
    if path.is_file() and hashlib.sha256(path.read_bytes()).hexdigest() == expected:
        return path
    url = "https://raw.githubusercontent.com/notofonts/noto-cjk/main/Sans/OTF/SimplifiedChinese/NotoSansCJKsc-Regular.otf"
    request = Request(url, headers={"User-Agent": "PagerMaid-Plugin-Card/1.0"})
    with urlopen(request, timeout=40) as response:
        data = response.read(24 * 1024 * 1024 + 1)
    if hashlib.sha256(data).hexdigest() != expected:
        raise RuntimeError("中文字体校验失败，请稍后重试。")
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=".cj-font-", dir=str(path.parent))
    try:
        with open(fd, "wb", closefd=True) as file:
            file.write(data)
        Path(temporary).replace(path)
    finally:
        Path(temporary).unlink(missing_ok=True)
    return path


def create_inventory_card(count, entries, uptime_seconds=None):
    """Keep every item in one image when the full caption cannot be sent."""
    from PIL import Image, ImageDraw, ImageFont

    header = create_count_card(count, uptime_seconds)
    try:
        with Image.open(header) as original:
            top = original.convert("RGB")
    finally:
        header.close()
    font_path = full_inventory_font()
    font = ImageFont.truetype(str(font_path), 30)
    probe = ImageDraw.Draw(top)
    lines = []
    for entry in entries:
        plain = html.unescape(re.sub(r"<[^>]+>", "", entry))
        for line in plain.splitlines():
            current = ""
            for char in line:
                if current and probe.textlength(current + char, font=font) > 1072:
                    lines.append(current)
                    current = ""
                current += char
            lines.append(current)
        lines.append("")
    if lines and not lines[-1]:
        lines.pop()
    height = 640 + max(1, len(lines)) * 46 + 32
    image = Image.new("RGB", (1200, height), "#05070d")
    image.paste(top, (0, 0))
    draw = ImageDraw.Draw(image)
    draw.line((64, 590, 1136, 590), fill="#1b2636", width=2)
    for index, line in enumerate(lines):
        draw.text((64, 640 + index * 46), line, font=font, fill="#c1cad8", anchor="ls")
    output = io.BytesIO()
    image.save(output, "PNG", optimize=True)
    output.name = "pagermaid-all-plugins.png"
    output.seek(0)
    return output


async def send_plugin_list(client, message, paths):
    paths = list(paths)
    entries = format_entries(paths)
    caption = count_caption(paths, entries)
    plain = html.unescape(re.sub(r"<[^>]+>", "", caption))
    uptime_seconds = await asyncio.to_thread(process_uptime_seconds)
    limit = 1024
    try:
        account = await client.get_me()
        if getattr(account, "is_premium", False) and not getattr(account, "is_bot", False):
            limit = 4096
    except Exception:
        pass
    image = None
    options = {"chat_id": message.chat.id, "parse_mode": enums.ParseMode.HTML}
    reply_id = getattr(message, "reply_to_message_id", None) or getattr(message, "reply_to_msg_id", None)
    if reply_id:
        options["reply_to_message_id"] = reply_id
    try:
        if len(plain.encode("utf-16-le")) // 2 <= limit:
            image = await asyncio.to_thread(create_count_card, len(paths), uptime_seconds)
            try:
                await client.send_photo(photo=image, caption=caption, **options)
            except Exception as exc:
                if "captiontoolong" not in type(exc).__name__.lower() and getattr(exc, "ID", "") != "CAPTION_TOO_LONG":
                    raise
                image.close()
                image = await asyncio.to_thread(create_inventory_card, len(paths), entries, uptime_seconds)
                await client.send_photo(photo=image, **options)
        else:
            image = await asyncio.to_thread(create_inventory_card, len(paths), entries, uptime_seconds)
            await client.send_photo(photo=image, **options)
        with contextlib.suppress(Exception):
            await message.delete()
    finally:
        if image is not None:
            image.close()


async def edit_result(message: Message, text: str) -> None:
    await message.edit(
        text,
        parse_mode=enums.ParseMode.HTML,
        disable_web_page_preview=True,
    )


def notes_menu() -> str:
    return (
        "<b>YanyuBot - 插件备注管理</b>\n\n"
        "<code>,cj set 插件名 新备注</code>　设置备注"
    )


@listener(
    is_plugin=True,
    outgoing=True,
    command="cj",
    description="列出已安装的 PagerMaid 插件及功能说明",
    parameters="<menu/set>",
    priority=1,
)
async def plugin_list(client: Client, message: Message):
    try:
        argument = (getattr(message, "arguments", None) or "").strip()
        parts = argument.split(maxsplit=2)
        action = parts[0].lower() if parts else ""

        if action in {"menu", "help", "备注"}:
            return await edit_result(message, notes_menu())
        if action == "set":
            if len(parts) < 3:
                return await edit_result(message, notes_menu())
            path = resolve_plugin(parts[1])
            if path is None:
                return await edit_result(message, "没有找到这个插件。")
            note = clean_description(parts[2])
            if note == "暂无功能说明":
                return await edit_result(message, "备注内容不能为空。")
            MANUAL_NOTES[path.name] = note
            save_notes()
            return await edit_result(
                message,
                f"已更新 <code>{html.escape(path.name)}</code> 的备注：\n\n"
                f"<blockquote>{html.escape(note)}</blockquote>",
            )
        if action:
            return await edit_result(message, notes_menu())

        await send_plugin_list(client, message, plugin_files(PLUGINS_DIR))
    except Exception as exc:
        await edit_result(message, "读取插件列表失败：" + html.escape(str(exc)))
